/**
 * n8n Code Node (JavaScript): Session Mini-Memory Router & Cluster Expansion Handler
 * Author: Marcos Vinicius Beregula Ferreira (UEL - LABGEP / NIGEP)
 *
 * Architecture Role (Pre-SLM Node):
 *   Replaces n8n's native LangChain 'Simple Memory' (Window Buffer Memory) to prevent:
 *     1. Context window overflow on CPU-bound SLMs (4,096 token limit).
 *     2. Cross-turn prompt contamination during tool calling.
 *     3. Redundant SLM/database calls when the user simply selects a K-Medoids cluster.
 *
 * Placement in n8n Workflow:
 *   [Webhook] ---> [Session Mini-Memory Router (THIS NODE)] ---> [IF: route_to_slm?]
 *                                                                   |-- true  --> [SLM Agent / Postgres]
 *                                                                   |-- false --> [Respond to Webhook]
 */

const SESSION_TTL_MS = 15 * 60 * 1000; // 15 minutes session expiration
const MAX_REFINEMENT_TURNS = 3;        // Auto-reset after 3 turns to avoid context contamination

// Initialize or retrieve global static memory store inside n8n V8 engine
// Note: n8n does not persist $getWorkflowStaticData('global') in 'manual' Editor Chat mode,
// so we mirror the session map in globalThis.__SLM_SESSIONS__ to support BOTH manual Chat UI and production Webhooks!
const staticData = $getWorkflowStaticData('global');
if (!globalThis.__SLM_SESSIONS__) {
  globalThis.__SLM_SESSIONS__ = staticData.sessions || {};
}
staticData.sessions = globalThis.__SLM_SESSIONS__;

const now = Date.now();

// Garbage collection: purge expired sessions to keep RAM footprint near zero
for (const [sid, sess] of Object.entries(staticData.sessions)) {
  if (!sess || (now - (sess.updatedAt || 0)) > SESSION_TTL_MS) {
    delete staticData.sessions[sid];
  }
}

// Extract incoming payload (from Load Session Memory Postgres node, Webhook, or Chat Trigger)
const inputItem = $input.first() ? $input.first().json : {};
const body = inputItem.body || inputItem;
const sessionId = String(inputItem.sessionId || body.sessionId || 'default-session').trim();
const rawMessage = String(inputItem.rawMessage || body.message || body.chatInput || inputItem.message || inputItem.chatInput || '').trim();
const normalizedMsg = rawMessage.toLowerCase();

// Retrieve session state from PostgreSQL slm_session_memory (if present) or fallback to staticData
let dbClusters = inputItem.db_clusters || null;
if (typeof dbClusters === 'string') {
  try { dbClusters = JSON.parse(dbClusters); } catch (_) { dbClusters = null; }
}

let session = (inputItem.db_last_term !== undefined || inputItem.db_clusters !== undefined)
  ? {
      sessionId,
      lastTerm: inputItem.db_last_term || null,
      turnCount: Number(inputItem.db_turn_count || 0),
      clusters: Array.isArray(dbClusters) ? dbClusters : null,
      updatedAt: now
    }
  : (staticData.sessions[sessionId] || {
      sessionId,
      lastTerm: null,
      turnCount: 0,
      clusters: null,
      updatedAt: now
    });

// Helper: Format budget items into a deterministic Markdown list without calling the SLM
function formatDeterministicTable(items, headerTitle) {
  const blocks = items.map((item, idx) => {
    const codigo = item.codigo || '-';
    const descricao = item.descricao || '-';
    const titulo = item.titulo && String(item.titulo).trim() ? String(item.titulo).trim() : '-';
    const detalhe = item.detalhe && String(item.detalhe).trim() ? String(item.detalhe).trim() : '-';
    return [
      `**${idx + 1}. Código: \`${codigo}\`**  `,
      `• **Descrição:** ${descricao}  `,
      `• **Título:** ${titulo}  `,
      `• **Detalhe:** ${detalhe}`
    ].join('\n');
  });

  return (
    `${headerTitle} (**${items.length} registros encontrados**):\n\n` +
    blocks.join('\n\n---\n\n') +
    `\n\n---\nAlgum corresponde ao que você precisa? Digite outra palavra-chave para nova busca.`
  );
}

// -----------------------------------------------------------------------------
// CASE 1: Explicit Context Reset Command
// -----------------------------------------------------------------------------
const resetPattern = /^(reiniciar|limpar|reset|nova busca|recomeçar|recomecar|cancelar|outro assunto)$/i;
if (resetPattern.test(normalizedMsg)) {
  delete staticData.sessions[sessionId];
  return [{
    json: {
      route_to_slm: false,
      acao_memoria: 'contexto_reiniciado',
      sessionId,
      save_last_term: '',
      save_turn_count: 0,
      save_clusters_json: 'null',
      output: 'Contexto da conversa reiniciado com sucesso. Digite a palavra-chave ou código da natureza de despesa que deseja pesquisar.'
    }
  }];
}

// -----------------------------------------------------------------------------
// CASE 2: User Selects a K-Medoids Cluster Option (e.g., "1", "opção 2", "grupo 3")
// -----------------------------------------------------------------------------
if (Array.isArray(session.clusters) && session.clusters.length > 0) {
  const choiceMatch = normalizedMsg.match(
    /^(?:op[cç][aã]o|grupo|item|topico|tópico|numero|número|quero o|quero a|ver o|ver a|abrir)?\s*([1-9])\b/i
  );

  if (choiceMatch) {
    const chosenGroupNum = parseInt(choiceMatch[1], 10);
    const chosenCluster = session.clusters.find(c => c.grupo === chosenGroupNum);

    if (chosenCluster && Array.isArray(chosenCluster.membros)) {
      const header = `Exibindo itens do **Grupo ${chosenCluster.grupo}** (${chosenCluster.descricaoGrupo})`;
      const responseText = formatDeterministicTable(chosenCluster.membros, header);

      // Keep clusters in session so the user can also inspect other options (e.g., "2" then "3")!
      session.turnCount += 1;
      session.updatedAt = now;
      staticData.sessions[sessionId] = session;

      return [{
        json: {
          route_to_slm: false,
          acao_memoria: 'expansao_cluster_direta',
          sessionId,
          grupoEscolhido: chosenGroupNum,
          totalItensGrupo: chosenCluster.membros.length,
          save_last_term: session.lastTerm || '',
          save_turn_count: session.turnCount,
          save_clusters_json: JSON.stringify(session.clusters),
          output: responseText
        }
      }];
    }
  }
}

// -----------------------------------------------------------------------------
// CASE 3: Incremental Refinement vs. Auto-Reset on Turn Limit / New Topic
// -----------------------------------------------------------------------------
const refinementPrefixPattern = /^(mas\s+|só\s+|so\s+|apenas\s+|somente\s+|especificamente\s+|para\s+|de\s+|do\s+|da\s+|tipo\s+|exceto\s+)/i;
const isShortRefinement = (
  session.lastTerm &&
  session.turnCount < MAX_REFINEMENT_TURNS &&
  (refinementPrefixPattern.test(normalizedMsg) || normalizedMsg.split(/\s+/).length <= 2) &&
  !/^(oi|olá|ola|bom dia|boa tarde|boa noite|ajuda|socorro)\b/i.test(normalizedMsg) &&
  !/^\d/.test(normalizedMsg)
);

let messageForSlm = rawMessage;
let memoryAction = 'nova_busca_limpa';

if (isShortRefinement && !normalizedMsg.includes(session.lastTerm.toLowerCase())) {
  // Lightweight context injection: combines previous search term with short modifier (~5 tokens total)
  const cleanModifier = rawMessage.replace(/^(?:(?:mas|só|so|apenas|somente|especificamente|para|de|do|da|tipo)\s+)+/i, '').trim();
  messageForSlm = `${session.lastTerm} ${cleanModifier}`.trim();
  session.turnCount += 1;
  memoryAction = 'refinamento_incremental';
} else {
  // Auto-reset session state to prevent cross-turn contamination in the SLM
  session = {
    sessionId,
    lastTerm: null,
    turnCount: 1,
    clusters: null,
    updatedAt: now
  };
  if (session.turnCount >= MAX_REFINEMENT_TURNS) {
    memoryAction = 'auto_reset_limite_turnos';
  }
}

session.updatedAt = now;
staticData.sessions[sessionId] = session;

return [{
  json: {
    route_to_slm: true,
    acao_memoria: memoryAction,
    sessionId,
    original_message: rawMessage,
    message: messageForSlm,
    turn_count: session.turnCount,
    save_last_term: session.lastTerm || '',
    save_turn_count: session.turnCount,
    save_clusters_json: 'null'
  }
}];

// Parse single-turn output from fine-tuned qwen2.5-budget:1.5b (Zero Memory Contamination)
const routerData = $('Session Mini-Memory Router').first().json;
const rawResponse = String($input.first().json.response || '').trim();

if (/^(oi|ol[áa]|bom dia|boa tarde|boa noite|ajuda)\b/i.test(routerData.original_message || '')) {
  return [{
    json: {
      execute_sql: false,
      sessionId: routerData.sessionId,
      acao_memoria: "saudacao",
      save_last_term: routerData.save_last_term || "",
      save_turn_count: routerData.save_turn_count || 0,
      save_clusters_json: "null",
      output: "Escreva palavras-chave para a natureza de despesa ou código parcial/integral.\nExemplos: Gasolina, Material gráfico, Serviço de limpeza predial, Software de Gestão, Reforma de Telhado, 3.3.90.30..."
    }
  }];
}

let parsed = null;
try {
  const jsonMatch = rawResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  parsed = null;
}

if (!parsed && rawResponse.length > 20 && !rawResponse.startsWith('{')) {
  return [{
    json: {
      execute_sql: false,
      sessionId: routerData.sessionId,
      acao_memoria: "resposta_normativa_ou_recusa",
      save_last_term: routerData.save_last_term || "",
      save_turn_count: routerData.save_turn_count || 0,
      save_clusters_json: "null",
      output: rawResponse
    }
  }];
}

const msgWords = String(routerData.message || '')
  .toLowerCase()
  .replace(/\b(de|da|do|das|dos|para|com|em|por|quero|preciso|comprar|contratar|adquirir)\b/gi, ' ')
  .trim()
  .split(/\s+/)
  .filter(w => w.length >= 3);

const termo1 = String((parsed && (parsed.termo1 || parsed.termo_busca)) || msgWords[0] || routerData.message || '').trim();
let termo2 = String((parsed && parsed.termo2) || (msgWords.length > 1 ? msgWords[msgWords.length - 1] : termo1)).trim();
if (termo2.toLowerCase() === 'seil' || termo2.toLowerCase() === 'seti' || !termo2) {
  termo2 = msgWords.length > 1 ? msgWords[msgWords.length - 1] : termo1;
}

const termoBusca = termo1.toLowerCase() === termo2.toLowerCase() ? termo1 : `${termo1} ${termo2}`;

return [{
  json: {
    execute_sql: true,
    sessionId: routerData.sessionId,
    termo_busca: termoBusca,
    termo1: termo1,
    termo2: termo2,
    acao_memoria: routerData.acao_memoria
  }
}];

/**
 * n8n Code Node (JavaScript): Dynamic K-Medoids Clustering + Session Mini-Memory Saver
 * Author: Marcos Vinicius Beregula Ferreira (UEL - LABGEP / NIGEP)
 *
 * Usage:
 *   Place this node immediately after the PostgreSQL / Vector Search node in n8n.
 *   - If query returns <= 7 items: formats deterministic table directly and updates session lastTerm.
 *   - If query returns > 7 items: executes in-memory K-Medoids clustering (k=4),
 *     stores the full member lists per cluster in $getWorkflowStaticData('global').sessions[sessionId]
 *     (outside the SLM context window), and outputs the k representative medoid options.
 *   - Latency overhead: < 15ms on CPU. Zero external npm dependencies.
 */

// Helper to tokenize and build lexical word set
function extractTokens(item) {
  const text = `${item.codigo || ''} ${item.descricao || ''} ${item.titulo || ''} ${item.detalhe || ''}`.toLowerCase();
  const words = text.match(/[a-zà-ÿ0-9]{3,}/g) || [];
  return new Set(words);
}

// Jaccard distance between two token sets (1.0 = disjoint, 0.0 = identical)
function jaccardDistance(setA, setB) {
  if (setA.size === 0 && setB.size === 0) return 0.0;
  let intersection = 0;
  for (const item of setA) {
    if (setB.has(item)) intersection++;
  }
  const union = setA.size + setB.size - intersection;
  return union === 0 ? 0.0 : 1.0 - (intersection / union);
}

// Cosine distance for vector embeddings (when pgvector embedding column is present)
function cosineDistance(vecA, vecB) {
  let dot = 0.0, normA = 0.0, normB = 0.0;
  for (let i = 0; i < vecA.length; i++) {
    dot += vecA[i] * vecB[i];
    normA += vecA[i] * vecA[i];
    normB += vecB[i] * vecB[i];
  }
  const denominator = Math.sqrt(normA) * Math.sqrt(normB);
  return denominator === 0 ? 1.0 : 1.0 - (dot / denominator);
}

// Build a clean, non-redundant label for a medoid item (avoids repeating titulo when identical to descricao)
function buildMedoidLabel(item) {
  const codigo = String(item.codigo || '-').trim();
  const desc = String(item.descricao || '-').trim();
  const tit = String(item.titulo || '').trim();
  const normDesc = desc.toLowerCase().replace(/[\s\-–—]+/g, ' ');
  const normTit = tit.toLowerCase().replace(/[\s\-–—]+/g, ' ');
  const extraTit = (tit && tit !== '-' && normTit !== normDesc && !normDesc.includes(normTit))
    ? ` (${tit})`
    : '';
  return `\`${codigo}\` — ${desc}${extraTit}`;
}

// Partitioning Around Medoids (PAM) Algorithm returning medoids AND full cluster member arrays
function runKMedoids(items, k = 4, maxIter = 25) {
  const n = items.length;
  if (n <= k) {
    return items.map((item, idx) => ({
      grupo: idx + 1,
      medoid: item,
      totalItensNoGrupo: 1,
      descricaoGrupo: buildMedoidLabel(item),
      membros: [item]
    }));
  }

  const hasEmbeddings = Array.isArray(items[0].embedding) && items[0].embedding.length > 0;
  const tokenSets = hasEmbeddings ? null : items.map(extractTokens);

  // Precompute pairwise distance matrix
  const distMatrix = Array.from({ length: n }, (_, i) =>
    Array.from({ length: n }, (_, j) => {
      if (i === j) return 0.0;
      if (hasEmbeddings) return cosineDistance(items[i].embedding, items[j].embedding);
      return jaccardDistance(tokenSets[i], tokenSets[j]);
    })
  );

  // Initialize medoids evenly spaced across dataset
  const step = Math.floor(n / k);
  let medoids = Array.from({ length: k }, (_, i) => Math.min(i * step, n - 1));

  let clusters = {};
  for (let iter = 0; iter < maxIter; iter++) {
    clusters = {};
    for (const m of medoids) clusters[m] = [];

    // Assignment phase: assign each item to closest medoid (each medoid anchors its own cluster)
    for (let i = 0; i < n; i++) {
      if (clusters[i] !== undefined) {
        clusters[i].push(i);
        continue;
      }
      let bestM = medoids[0];
      let bestDist = distMatrix[i][bestM];
      for (let mIdx = 1; mIdx < medoids.length; mIdx++) {
        const m = medoids[mIdx];
        if (distMatrix[i][m] < bestDist) {
          bestDist = distMatrix[i][m];
          bestM = m;
        }
      }
      clusters[bestM].push(i);
    }

    // Update phase: select new medoid minimizing sum of distances within cluster
    let changed = false;
    const newMedoids = [];
    for (const m of medoids) {
      const members = clusters[m];
      if (!members || members.length === 0) {
        newMedoids.push(m);
        continue;
      }
      let bestCand = m;
      let minTotalDist = Infinity;
      for (const cand of members) {
        let sumDist = 0;
        for (const other of members) sumDist += distMatrix[cand][other];
        if (sumDist < minTotalDist) {
          minTotalDist = sumDist;
          bestCand = cand;
        }
      }
      if (bestCand !== m) changed = true;
      newMedoids.push(bestCand);
    }
    medoids = newMedoids;
    if (!changed) break;
  }

  // Format output clusters with real medoid and full member array for session state memory
  const uniqueMedoids = [...new Set(medoids)];
  return uniqueMedoids.map((m, idx) => {
    const memberIndices = clusters[m] && clusters[m].length > 0 ? clusters[m] : [m];
    const memberItems = memberIndices.map(i => items[i]);
    return {
      grupo: idx + 1,
      medoid: items[m],
      totalItensNoGrupo: memberItems.length,
      descricaoGrupo: buildMedoidLabel(items[m]),
      membros: memberItems
    };
  });
}

// Helper to format small result sets directly with clean Markdown line breaks
function formatDirectResults(items) {
  if (items.length === 0) {
    return 'Não encontrei esta despesa no banco de dados. Tente descrever de outra forma, como o tipo do material ou serviço.';
  }
  const blocks = items.map((item, idx) => {
    const codigo = item.codigo || '-';
    const descricao = item.descricao || '-';
    const titulo = item.titulo && String(item.titulo).trim() ? String(item.titulo).trim() : '-';
    const detalhe = item.detalhe && String(item.detalhe).trim() ? String(item.detalhe).trim() : '-';
    return [
      `**${idx + 1}. Código: \`${codigo}\`**  `,
      `• **Descrição:** ${descricao}  `,
      `• **Título:** ${titulo}  `,
      `• **Detalhe:** ${detalhe}`
    ].join('\n');
  });
  return (
    `Encontrei **${items.length} registro(s)**:\n\n` +
    blocks.join('\n\n---\n\n') +
    `\n\n---\nAlgum corresponde ao que você precisa? Posso refinar a busca.`
  );
}

// ----------------------------------------------------
// n8n Entrypoint Execution + Session Memory Persistence
// ----------------------------------------------------
const rawItems = $input.all().map(item => item.json).filter(item => item && item.codigo);
const totalResults = rawItems.length;

// Retrieve session metadata from static data (mirrored in globalThis.__SLM_SESSIONS__ so manual Editor Chat works too)
const staticData = $getWorkflowStaticData('global');
if (!globalThis.__SLM_SESSIONS__) {
  globalThis.__SLM_SESSIONS__ = staticData.sessions || {};
}
staticData.sessions = globalThis.__SLM_SESSIONS__;

const firstInput = $input.first() ? $input.first().json : {};
let upstreamSessionId = '';
let upstreamTerm = '';
let upstreamTurnCount = 1;
try {
  if (typeof $ === 'function') {
    const routerNode = $('Session Mini-Memory Router');
    if (routerNode && routerNode.first() && routerNode.first().json) {
      upstreamSessionId = routerNode.first().json.sessionId || '';
      upstreamTurnCount = Number(routerNode.first().json.turn_count || 1);
    }
  }
} catch (_) {
  // Ignore if upstream node is named differently or in standalone test
}

const sessionId = String(firstInput.sessionId || upstreamSessionId || 'default-session').trim();
const searchedTerm = String(firstInput.termo_busca || firstInput.lastTerm || upstreamTerm || '').trim();

const currentSession = staticData.sessions[sessionId] || {
  sessionId,
  lastTerm: searchedTerm || null,
  turnCount: upstreamTurnCount,
  clusters: null,
  updatedAt: Date.now()
};

if (searchedTerm) {
  currentSession.lastTerm = searchedTerm;
}
currentSession.turnCount = upstreamTurnCount;
currentSession.updatedAt = Date.now();

if (totalResults <= 7) {
  // Pass-through: Few items, clear cluster state and return deterministic formatted table
  currentSession.clusters = null;
  staticData.sessions[sessionId] = currentSession;

  return [{
    json: {
      acao: 'exibicao_direta',
      sessionId,
      totalEncontrado: totalResults,
      itens: rawItems,
      save_last_term: currentSession.lastTerm || '',
      save_turn_count: currentSession.turnCount,
      save_clusters_json: 'null',
      output: formatDirectResults(rawItems)
    }
  }];
} else {
  // High count: cluster via K-Medoids (k=4 based on 1st local Silhouette peak) and save to Mini-Memory
  const k = 4;
  const clusterResults = runKMedoids(rawItems, k);

  // Save full cluster members inside n8n Session Mini-Memory (outside the SLM context window!)
  currentSession.clusters = clusterResults;
  staticData.sessions[sessionId] = currentSession;

  const formattedDisambiguationPrompt =
    `Sua busca retornou **${totalResults} resultados**. Para facilitar a localização sem sobrecarregar a tela, agrupei os itens nos **${k} temas mais representativos**:\n\n` +
    clusterResults.map(c => `${c.grupo}. **Opção ${c.grupo}** *(${c.totalItensNoGrupo} itens)*: ${c.descricaoGrupo}`).join('\n\n') +
    `\n\n---\nDigite o **número da opção (1 a ${k})** para listar os itens daquele grupo, ou envie um termo mais específico para refinar.`;

  return [{
    json: {
      acao: 'desambiguacao_kmedoids_salva_em_memoria',
      sessionId,
      totalEncontrado: totalResults,
      kClusters: k,
      gruposSugeridos: clusterResults.map(c => ({
        grupo: c.grupo,
        totalItensNoGrupo: c.totalItensNoGrupo,
        descricaoGrupo: c.descricaoGrupo,
        medoid: c.medoid
      })),
      save_last_term: currentSession.lastTerm || '',
      save_turn_count: currentSession.turnCount,
      save_clusters_json: JSON.stringify(clusterResults),
      output: formattedDisambiguationPrompt
    }
  }];
}
